import pytest
from ta_attenuator.fading_registry import FadingRegistry


def test_getting_fading_when_registry_is_empty_causes_exception():
    from ta_attenuator.fading_registry import FadingRegistryEmpty
    test_registry = FadingRegistry()
    with pytest.raises(FadingRegistryEmpty):
        test_registry.get_fading('JFW_168')
